def parse_inline_spoiler(inline: 'InlineParser', m: Match[str], state:
    'InlineState') ->int:
    text = m.group('spoiler_text')
    children = inline.parse(text, state)
    token = {'type': 'inline_spoiler', 'children': children}
    state.append_token(token)
    return m.end()


def render_inline_spoiler(renderer: 'BaseRenderer', text: str) ->str:
    return '<span class="spoiler">' + text + '</span>'


def spoiler(md: 'Markdown') ->None:
    md.inline.register_rule('inline_spoiler', INLINE_SPOILER_PATTERN)
    md.inline.rules.append('inline_spoiler')
    md.renderer.register_rule('inline_spoiler', render_inline_spoiler)
    md.block.register_rule('block_spoiler', _BLOCK_SPOILER_START)
    md.block.rules.append('block_spoiler')
    md.renderer.register_rule('block_spoiler', render_block_spoiler)
